 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Connect every pair of 1 markers on a 45-degree diagonal; retain any
    # 6 marker on the line and extend its color along the same diagonal ray.
    ones = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    sixes = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 6]
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if abs(r2-r1) != abs(c2-c1):
                continue
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            line = [(r1+k*dr,c1+k*dc) for k in range(abs(r2-r1)+1)]
            for r,c in line:
                if out[r][c] != 6:
                    out[r][c] = 1
            # A 6 on the connecting diagonal extends to the grid edge on both sides.
            for sr,sc in sixes:
                if (sr-r1)*(c2-c1) == (sc-c1)*(r2-r1):
                    for sign in (-1,1):
                        r,c = sr,sc
                        while 0 <= r < len(grid) and 0 <= c < len(grid[0]):
                            out[r][c] = 6
                            r += sign*dr
                            c += sign*dc
    return out
