    sixes = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 6]
    # Connect pairs of 1s with a 45-degree diagonal segment.
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for k in range(abs(r2-r1)+1):
                    r,c = r1+k*dr,c1+k*dc
                    if out[r][c] != 6:
                        out[r][c] = 1
    # Each 6 extends along its down-right/up-left diagonal to both grid edges.
    for r,c in sixes:
        rr,cc = r,c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 6
            rr -= 1; cc -= 1
        rr,cc = r+1,c+1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 6
            rr += 1; cc += 1
